CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,category TEXT,price_text TEXT,size_text TEXT,description TEXT,seo_title TEXT,seo_description TEXT,is_published BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS projects(id BIGSERIAL PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,summary TEXT,content TEXT,is_published BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts(id BIGSERIAL PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,excerpt TEXT,content TEXT,seo_title TEXT,seo_description TEXT,is_published BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leads(id BIGSERIAL PRIMARY KEY,name TEXT,phone TEXT NOT NULL,product TEXT,size_text TEXT,address TEXT,note TEXT,utm_source TEXT,utm_medium TEXT,utm_campaign TEXT,gclid TEXT,status TEXT DEFAULT 'new',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_leads_created_at ON leads(created_at DESC);CREATE INDEX IF NOT EXISTS idx_products_slug ON products(slug);CREATE INDEX IF NOT EXISTS idx_posts_slug ON posts(slug);